'use strict';
// Verify the partition table actually GENERATED by arduino-cli, not only CSV.
// A default 1.25 MiB C3 partition table must never pass new C3+SD packaging.
const fs=require('node:fs'),assert=require('node:assert/strict');
const FLASH_BYTES=0x400000,APP_BYTES=0x1E0000;
const EXPECTED={
  nvs:{type:1,subtype:2,offset:0x9000,size:0x4000},
  otadata:{type:1,subtype:0,offset:0xd000,size:0x2000},
  phy_init:{type:1,subtype:1,offset:0xf000,size:0x1000},
  app0:{type:0,subtype:0x10,offset:0x10000,size:APP_BYTES},
  app1:{type:0,subtype:0x11,offset:0x200000,size:APP_BYTES},
};
function parsePartitions(buffer){
  assert(buffer.length>=32 && buffer.length<=0x1000,'bad partition-table size');
  const entries=[];
  for(let index=0;index+32<=buffer.length;index+=32){
    if(buffer.readUInt16LE(index)!==0x50aa)break;
    const type=buffer[index+2],subtype=buffer[index+3];
    const offset=buffer.readUInt32LE(index+4),size=buffer.readUInt32LE(index+8);
    const label=buffer.subarray(index+12,index+28).toString('utf8').split('\0')[0];
    entries.push({label,type,subtype,offset,size});
  }
  return entries;
}
function verify(buffer){
  const entries=parsePartitions(buffer);
  assert.equal(entries.length,Object.keys(EXPECTED).length,'unexpected partitions or SPIFFS in C3+SD');
  const named=Object.fromEntries(entries.map(p=>[p.label,p]));
  for(const [name,want] of Object.entries(EXPECTED))
    assert.deepEqual(named[name],{label:name,...want},'bad partition '+name);
  for(const entry of entries){
    assert(entry.size>0&&entry.offset+entry.size<=FLASH_BYTES,'partition exceeds 4MiB');
    if(entry.type===0)assert.equal(entry.offset%0x10000,0,'app must align to 64 KiB');
    for(const other of entries){
      if(other===entry)continue;
      assert(entry.offset+entry.size<=other.offset || other.offset+other.size<=entry.offset,'partitions overlap');
    }
  }
  console.log('PASS: C3+SD 4 MiB custom table; two '+APP_BYTES+'-byte OTA slots, no SPIFFS');
  return entries;
}
if(require.main===module){
  if(!process.argv[2])throw Error('Usage: node tools/verify-c3-sd-layout.cjs <compiled partitions.bin>');
  verify(fs.readFileSync(process.argv[2]));
}
module.exports={parsePartitions,verify,EXPECTED,FLASH_BYTES,APP_BYTES};
